import React, { useMemo, useRef, useState } from 'react';
import './App.css';

type Coordinate = { row: number; col: number };
type NavigationKey = 'ArrowLeft' | 'ArrowRight' | 'ArrowUp' | 'ArrowDown' | 'Home' | 'End';

const MIN_SIZE = 2;
const MAX_SIZE = 20;
const NAVIGATION_KEYS: NavigationKey[] = [
  'ArrowLeft',
  'ArrowRight',
  'ArrowUp',
  'ArrowDown',
  'Home',
  'End'
];

function clampSize(raw: string): number {
  const parsed = Number(raw);
  if (!Number.isFinite(parsed)) return MIN_SIZE;
  return Math.min(MAX_SIZE, Math.max(MIN_SIZE, Math.trunc(parsed)));
}

function cellId(row: number, col: number): string {
  return 'chessboard-cell-' + row + '-' + col;
}

export default function App() {
  const [size, setSize] = useState(8);
  const [selected, setSelected] = useState<Coordinate | null>(null);
  const [focusIndex, setFocusIndex] = useState(0);
  const cellRefs = useRef<Array<HTMLButtonElement | null>>([]);

  const rows = useMemo(() => Array.from({ length: size }, (_, row) => row), [size]);
  const cols = useMemo(() => Array.from({ length: size }, (_, col) => col), [size]);

  const isSelected = (row: number, col: number): boolean => (
    selected?.row === row && selected.col === col
  );

  const isQueenReachable = (row: number, col: number): boolean => {
    if (!selected || isSelected(row, col)) return false;
    const rowDistance = Math.abs(row - selected.row);
    const colDistance = Math.abs(col - selected.col);
    return rowDistance === 0 || colDistance === 0 || rowDistance === colDistance;
  };

  const queenMoves = useMemo(() => {
    if (!selected) return 0;
    let count = 0;
    for (let row = 0; row < size; row += 1) {
      for (let col = 0; col < size; col += 1) {
        if (isQueenReachable(row, col)) count += 1;
      }
    }
    return count;
  }, [selected, size]);

  const selectionStatus = selected
    ? 'Selected: row ' + (selected.row + 1) + ', column ' + (selected.col + 1)
    : 'Selected: none';

  const onSizeChange = (raw: string) => {
    setSize(clampSize(raw));
    setSelected(null);
    setFocusIndex(0);
  };

  const onSelectCell = (row: number, col: number) => {
    setSelected({ row, col });
  };

  const cellLabel = (row: number, col: number): string => {
    const base = 'Row ' + (row + 1) + ', column ' + (col + 1);
    if (isSelected(row, col)) return base + ', selected';
    if (isQueenReachable(row, col)) return base + ', reachable by queen';
    return base;
  };

  const focusCell = (index: number) => {
    setFocusIndex(index);
    cellRefs.current[index]?.focus();
  };

  const onCellKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>, index: number) => {
    const key = event.key as NavigationKey;
    if (!NAVIGATION_KEYS.includes(key)) return;

    event.preventDefault();
    const row = Math.floor(index / size);
    const col = index % size;
    let nextIndex = index;

    if (key === 'ArrowLeft') nextIndex = row * size + (col + size - 1) % size;
    else if (key === 'ArrowRight') nextIndex = row * size + (col + 1) % size;
    else if (key === 'ArrowUp') nextIndex = ((row + size - 1) % size) * size + col;
    else if (key === 'ArrowDown') nextIndex = ((row + 1) % size) * size + col;
    else if (key === 'Home') nextIndex = row * size;
    else if (key === 'End') nextIndex = row * size + size - 1;

    focusCell(nextIndex);
  };

  return (
    <main className='page'>
      <section className='card'>
        <h1>Chessboard Click / Highlight</h1>
        <p className='subtitle'>
          Select one square, inspect every blocker-free queen move, and navigate the grid by keyboard.
        </p>

        <label className='size' htmlFor='board-size'>
          Board size (N)
          <input
            id='board-size'
            type='number'
            min={MIN_SIZE}
            max={MAX_SIZE}
            value={size}
            onChange={(event) => onSizeChange(event.target.value)}
          />
        </label>

        <p id='board-status' className='status' role='status' aria-live='polite'>
          <span className='selection-status'>{selectionStatus}</span>
          {selected && <span className='reachability-status'>Queen moves: {queenMoves}</span>}
        </p>

        <div
          className='board'
          role='grid'
          aria-label='Interactive chessboard'
          aria-describedby='board-status'
          aria-rowcount={size}
          aria-colcount={size}
          style={{ gridTemplateColumns: `repeat(${size}, minmax(0, 1fr))` }}
        >
          {rows.map((row) =>
            cols.map((col) => {
              const index = row * size + col;
              const dark = (row + col) % 2 === 1;
              const active = isSelected(row, col);
              const reachable = isQueenReachable(row, col);
              const className = [
                'cell',
                dark ? 'cell--dark' : 'cell--light',
                active ? 'cell--active' : '',
                reachable ? 'cell--reachable' : ''
              ].filter(Boolean).join(' ');

              return (
                <button
                  key={cellId(row, col)}
                  id={cellId(row, col)}
                  ref={(element) => {
                    cellRefs.current[index] = element;
                  }}
                  className={className}
                  type='button'
                  role='gridcell'
                  data-row={row}
                  data-col={col}
                  data-reachable={reachable ? 'true' : undefined}
                  aria-rowindex={row + 1}
                  aria-colindex={col + 1}
                  aria-label={cellLabel(row, col)}
                  aria-pressed={active}
                  tabIndex={focusIndex === index ? 0 : -1}
                  onFocus={() => setFocusIndex(index)}
                  onKeyDown={(event) => onCellKeyDown(event, index)}
                  onClick={() => onSelectCell(row, col)}
                />
              );
            })
          )}
        </div>
      </section>
    </main>
  );
}

